  @doc false
  def render(name, assigns) when is_atom(name) do
    case @icon_paths do
      %{^name => paths} ->
        attrs = assigns_to_attributes(assigns)
        assigns = assigns |> assign(:attrs, attrs) |> assign(:paths, raw(paths))
        render_icon(assigns)

      _ ->
        raise ArgumentError, "unknown Lucide icon: #{inspect(name)}"
    end
  end

  defp render_icon(assigns) do
    ~H"""
    <svg
      {@attrs}
      xmlns="http://www.w3.org/2000/svg"
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="2"
      stroke-linecap="round"
      stroke-linejoin="round"
    >
      {@paths}
    </svg>
    """
  end

